(() => {
  'use strict';

  const WRAPPER_SEL = '.box-search-results';
  const SCOPE_INNER = '.elementor-shortcode';
  const DEBOUNCE_MS = 600;
  const IDLE_MS     = 800;

  // i18n como no PHP
  function lang2(){
    const l = (document.documentElement.getAttribute('lang') || '').toLowerCase();
    if (l.startsWith('pt')) return 'pt';
    if (l.startsWith('es')) return 'es';
    return 'en';
  }
  function noResultsText(){
    const m = { pt: 'Nenhum resultado encontrado.', es: 'No se encontraron resultados.', en: 'No results found.' };
    return m[lang2()] || m.en;
  }

  // visibilidade real (ignora opacity 0)
  function isReallyVisible(el){
    if (!el || el.nodeType !== 1) return false;
    if (el.hasAttribute('hidden')) return false;
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') return false;
    if (el.getClientRects().length === 0) return false;
    if (el.classList.contains('geo-hidden-by-parent') || el.classList.contains('geo-hidden-by-child')) return false;
    for (let p = el.parentElement; p && p !== document.body; p = p.parentElement){
      const cps = getComputedStyle(p);
      if (p.hasAttribute('hidden') || cps.display === 'none' || cps.visibility === 'hidden') return false;
    }
    return true;
  }
  function visibleCount(ul){
    if (!ul) return 0;
    let n = 0;
    Array.from(ul.children).forEach(li => { if (li.tagName === 'LI' && isReallyVisible(li)) n++; });
    return n;
  }

  function getRefs(root){
    const scope = root.querySelector(SCOPE_INNER) || root;
    return {
      scope,
      listSol:   scope.querySelector('.search-results__list--solutions'),
      listOther: scope.querySelector('.search-results__list--others'),
      headSol:   scope.querySelector('.search-results__heading:not(.search-results__heading--others)'),
      headOther: scope.querySelector('.search-results__heading--others')
    };
  }

 function reconcileWrapper(root){
  const { scope, listSol, listOther, headSol, headOther } = getRefs(root);
  if (!scope) return;

  const cSol   = visibleCount(listSol);
  const cOther = visibleCount(listOther);
  const hasAny = (cSol > 0) || (cOther > 0);

  // mostra/esconde seções vazias (sem remover nada)
  if (headSol)   headSol.style.display   = (listSol && cSol   > 0) ? '' : 'none';
  if (headOther) headOther.style.display = (listOther && cOther > 0) ? '' : 'none';
  if (listSol)   listSol.style.display   = (cSol   > 0) ? '' : 'none';
  if (listOther) listOther.style.display = (cOther > 0) ? '' : 'none';

  // Mensagens:
  // - serverMsg: a que vem do PHP (sem .js-sr-injected)
  // - injected : a que o JS cria (com .js-sr-injected)
  const serverMsg = scope.querySelector('.no-results:not(.js-sr-injected)');
  let   injected  = scope.querySelector('.no-results.js-sr-injected');

  if (hasAny) {
    // Há itens visíveis: esconda qualquer mensagem existente
    if (serverMsg) serverMsg.style.display = 'none';
    if (injected)  injected.style.display  = 'none';
  } else {
    // Não há itens visíveis:
    if (serverMsg) {
      // Use a mensagem do PHP como canônica; nunca duplique
      serverMsg.textContent = serverMsg.textContent?.trim() || noResultsText();
      serverMsg.style.display = '';
      if (injected) injected.remove(); // garante que não haverá 2 mensagens
    } else {
      // Não veio do PHP -> podemos injetar a nossa
      if (!injected) {
        injected = document.createElement('p');
        injected.className = 'no-results js-sr-injected';
        injected.textContent = noResultsText();
        scope.appendChild(injected);
      } else {
        injected.textContent = noResultsText();
        injected.style.display = '';
      }
    }
  }
}

  // assinatura usada para esperar “silêncio” do geotargeting
  function geoSignature(wrappers){
    let a = document.querySelectorAll('.geo-hidden-by-parent').length;
    let b = document.querySelectorAll('.geo-hidden-by-child').length;
    let c = 0, d = 0;
    wrappers.forEach(w => {
      const { listSol, listOther } = getRefs(w);
      c += (listSol   ? listSol.querySelectorAll(':scope > li').length   : 0);
      d += (listOther ? listOther.querySelectorAll(':scope > li').length : 0);
    });
    return `${a}:${b}:${c}:${d}:wrappers=${wrappers.length}`;
  }

  let debTimer = null, idleTimer = null, lastSig = '';

  function waitIdleThen(fn, wrappers){
    clearTimeout(idleTimer);
    const sigNow = geoSignature(wrappers);
    if (sigNow !== lastSig) {
      lastSig = sigNow;
      idleTimer = setTimeout(() => waitIdleThen(fn, wrappers), IDLE_MS);
      return;
    }
    fn(wrappers);
  }

  function schedule(wrappers){
    clearTimeout(debTimer);
    debTimer = setTimeout(() => waitIdleThen(reconcileAll, wrappers), DEBOUNCE_MS);
  }

  function reconcileAll(wrappers){
    wrappers.forEach(reconcileWrapper);
  }

  function boot(){
    const wrappers = Array.from(document.querySelectorAll(WRAPPER_SEL));

    // limpa mensagens antigas soltas (caso versão anterior tenha injetado no body)
    document.querySelectorAll('.no-results.js-sr-injected').forEach(p => {
      if (!p.closest(WRAPPER_SEL)) p.remove();
    });

    // se não há wrappers de resultados nesta página, não faz nada
    if (!wrappers.length) return;

    // observa mudanças e agenda reconciliar
    const mo = new MutationObserver(() => schedule(wrappers));
    mo.observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['class','style','hidden','aria-hidden']
    });

    // hook opcional no cleanGeoMenu, se existir
    if (typeof window.cleanGeoMenu === 'function' && !window.cleanGeoMenu.__srWrapped){
      const orig = window.cleanGeoMenu;
      window.cleanGeoMenu = function(...args){
        const r = orig.apply(this, args);
        schedule(wrappers);
        return r;
      };
      window.cleanGeoMenu.__srWrapped = true;
    }

    // Elementor (opcional)
    if (window.elementorFrontend?.hooks) {
      const refresh = () => schedule(wrappers);
      elementorFrontend.hooks.addAction('frontend/element_ready/global', refresh);
      elementorFrontend.hooks.addAction('frontend/element_ready/container', refresh);
      elementorFrontend.hooks.addAction('frontend/element_ready/jet-listing-grid.default', refresh);
    }

    // disparos iniciais e tardios
    schedule(wrappers);
    setTimeout(() => schedule(wrappers), 700);
    setTimeout(() => schedule(wrappers), 1400);

    // API manual (se precisar)
    window.SearchResultsGeoAware = { refresh: () => schedule(wrappers) };
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once:true });
  } else {
    boot();
  }
  window.addEventListener('load', () => {
    const wrappers = Array.from(document.querySelectorAll(WRAPPER_SEL));
    if (wrappers.length) schedule(wrappers);
  });
})();
